<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {request} from '@/service/request';
import {useAuthStore} from '@/store/modules/auth';
defineOptions({name:'ChatSettings'});
interface ChatSettings {revokeSeconds:number;images:{maxEdge:number;quality:number;pngCompression:number};videos:{maxHeight:number;maxFps:number;crf:number;audioKbps:number;maxKbps:number;concurrency:number;coverMaxEdge:number;coverQuality:number}}
const auth=useAuthStore(),busy=ref(false),error=ref('');
const config=reactive<ChatSettings>({revokeSeconds:120,images:{maxEdge:2560,quality:85,pngCompression:6},videos:{maxHeight:1080,maxFps:30,crf:23,audioKbps:128,maxKbps:5000,concurrency:1,coverMaxEdge:1280,coverQuality:78}});
onMounted(async()=>{const result=await request<ChatSettings>({url:'/chat-settings'});if(result.data)Object.assign(config,result.data);else error.value='私聊配置读取失败，请检查后端及数据库迁移';});
async function save(){busy.value=true;try{const result=await request<ChatSettings>({url:'/chat-settings',method:'post',data:config});if(!result.error){error.value='';window.$message?.success('私聊配置已保存，新发送消息及新上传媒体生效');}}finally{busy.value=false;}}
</script>
<template><NCard title="私聊配置" :bordered="false"><NAlert v-if="error" type="error" class="mb-16px">{{error}}</NAlert><NForm :disabled="auth.isReadOnly" label-placement="left" label-width="150"><NFormItem label="消息撤销时限"><NInputNumber v-model:value="config.revokeSeconds" :min="0" :max="86400" :precision="0" /><span class="ml-12px">秒，0为禁用撤销</span></NFormItem><NDivider title-placement="left">私聊图片压缩</NDivider><NFormItem label="最长边"><NInputNumber v-model:value="config.images.maxEdge" :min="64" :max="16384" /><span class="ml-12px">px</span></NFormItem><NFormItem label="编码质量"><NInputNumber v-model:value="config.images.quality" :min="1" :max="100" /></NFormItem><NFormItem label="PNG压缩级别"><NInputNumber v-model:value="config.images.pngCompression" :min="0" :max="9" /></NFormItem><NAlert type="info" class="mb-16px">图片保持原格式；勾选原图时跳过压缩。私聊缓存长期保留，由用户单独清理。</NAlert><NDivider title-placement="left">私聊视频压缩</NDivider><NFormItem label="最高短边分辨率"><NInputNumber v-model:value="config.videos.maxHeight" :min="144" :max="2160" /></NFormItem><NFormItem label="最高帧率"><NInputNumber v-model:value="config.videos.maxFps" :min="1" :max="60" /></NFormItem><NFormItem label="CRF"><NInputNumber v-model:value="config.videos.crf" :min="0" :max="40" /></NFormItem><NFormItem label="最大视频码率"><NInputNumber v-model:value="config.videos.maxKbps" :min="100" :max="30000" /><span class="ml-12px">kbps</span></NFormItem><NFormItem label="音频码率"><NInputNumber v-model:value="config.videos.audioKbps" :min="32" :max="320" /><span class="ml-12px">kbps</span></NFormItem><NFormItem label="转码并发"><NInputNumber v-model:value="config.videos.concurrency" :min="1" :max="4" /></NFormItem><NFormItem label="封面最长边"><NInputNumber v-model:value="config.videos.coverMaxEdge" :min="64" :max="4096" /></NFormItem><NFormItem label="封面质量"><NInputNumber v-model:value="config.videos.coverQuality" :min="1" :max="100" /></NFormItem><NButton type="primary" :loading="busy" :disabled="auth.isReadOnly||!!error" @click="save">保存私聊配置</NButton></NForm></NCard></template>
